def moore_bound(d, g):
    if g % 2 == 1:
        k = (g - 1) // 2
        return 1 + d * sum((d - 1)**i for i in range(k))
    else:
        k = g // 2
        return 2 * sum((d - 1)**i for i in range(k))

print(f"Moore bound for d=5, g=6: {moore_bound(5, 6)}")

