import random

def is_girth_at_least_6(adj, n):
    # Check for cycles of length 3, 4, 5
    # BFS from each node
    for start_node in range(n):
        # dist[v] = (distance, parent)
        dist = {start_node: (0, -1)}
        queue = [start_node]
        while queue:
            u = queue.pop(0)
            d, p = dist[u]
            if d >= 2: # Only need to check up to length 5
                continue
            for v in adj[u]:
                if v == p:
                    continue
                if v in dist:
                    # Cycle found
                    cycle_len = d + dist[v][0] + 1
                    if cycle_len < 6:
                        return False
                else:
                    dist[v] = (d + 1, u)
                    queue.append(v)
    return True

def solve():
    n = 22
    d = 5

    # Try to build a 5-regular graph with 22 vertices and girth >= 6
    # Using a randomized local search

    # Start with a random 5-regular graph
    # A simple way to get a 5-regular graph is to take 5 perfect matchings

    for _ in range(10000):
        adj = [set() for _ in range(n)]
        edges = []

        # Generate 5 perfect matchings
        for _ in range(d):
            nodes = list(range(n))
            random.shuffle(nodes)
            for i in range(0, n, 2):
                u, v = nodes[i], nodes[i+1]
                if v not in adj[u]:
                    adj[u].add(v)
                    adj[v].add(u)
                    edges.append(tuple(sorted((u, v))))

        # Check if it's 5-regular
        if all(len(adj[i]) == d for i in range(n)):
            if is_girth_at_least_6(adj, n):
                return edges
    return None

